  "wp.message.26a6374fbf59": "Add-on Pixflow tidak dapat dimulai. Periksa kompatibilitas plugin Pixflow Anda, lalu muat ulang. Fitur lain mungkin tetap tersedia.",
  "wp.message.ca7714cffbcc": "Aktifkan Pro",
  "wp.message.197c83a2f752": "Pulihkan alat premium dengan add-on Pro. Lisensi, konten, dan pengaturan tersimpan tetap dipertahankan. Jika menggunakan autentikasi dua faktor Bricks, aktifkan kembali di pengaturan setelah mengaktifkan Pro.",
  "wp.message.2ffdcbc380ea": "Bangun di builder favorit Anda. Tambahkan anotasi, suara, sistem desain, dan pembuatan gambar ke alur kerja.",
  "wp.proRepair.title": "Pixflow Design Pro perlu diperiksa",
  "wp.proRepair.incomplete": "Beberapa file Pro hilang atau telah berubah. Instal ulang ZIP Pro terbaru dari akun Pixflow Anda. Lisensi, konten, dan pengaturan yang tersimpan akan dipertahankan.",
  "wp.proRepair.incompatible": "Add-on Pro yang terpasang tidak dapat dimuat pada versi Pixflow ini. Periksa pemberitahuan plugin dan perbarui Free dan Pro ke versi yang kompatibel. Lisensi, konten, dan pengaturan yang tersimpan akan dipertahankan.",
  "wp.proRepair.checkPlugins": "Periksa plugin terpasang",
  "wp.message.40ed1102964b": "Periksa uji coba Pro",
  "wp.message.e9cccd3ef5fc": "Tidak dapat menyimpan penutupan. Coba lagi.",
  "wp.message.1372089fb797": "Tutup banner Pixflow Pro",
  "wp.message.5e3ba715018d": "Unduh Pro",
  "wp.message.fb2e6d87b44c": "Lebih banyak kemungkinan dengan Pixflow Design Pro",
  "wp.message.9934717ca744": "Muat ulang halaman ini dan coba lagi.",
  "wp.message.7c78f9990490": "Mulai uji coba Pro 7 hari",
  "wp.message.f89b4dcf2c2e": "Coba Pro selama 7 hari",
  "wp.message.69ecce9deb2d": "Anda tidak dapat menutup pemberitahuan ini.",
  "wp.message.927384e7eed8": "Paket Pixflow Anda mencakup Pro",
